  "servers.settings.publicHelp": "<b>Полезно знать:</b> через playit.gg или ретранслятор игроки подключаются через этот сервис, это добавляет задержку, а баны по IP не работают (все будто заходят с адреса сервиса). Онлайн-режим в любом случае не пустит самозванцев. В первый раз Windows может спросить, можно ли Java использовать сеть: разреши.",
