  "servers.settings.tunnelHint.playit": "Если выполнен вход в аккаунт Microsoft, сначала пробуется ResinCraft Relay. Иначе playit.gg: бесплатный и сделан для Minecraft, друзья получают постоянный адрес вида name.joinmc.link. При первом запуске нужно связать ResinCraft с аккаунтом playit.gg в браузере (гостевого аккаунта хватит). Если ничего не сработает, используется ретранслятор bore.",
  "servers.settings.tunnelHint.relay": "Обходит роутер. Используй, если роутер даёт адрес, до которого друзья не могут достучаться. Адрес меняется при каждом запуске.",
