  "servers.multicore.reason.plugins": "Плагины не могут сделать тик многоядерным: они работают в главном потоке сервера. Paper и так выполняет работу с чанками на других ядрах. Единственный способ выполнять сам тик на нескольких ядрах — сменить серверное ПО на Folia.",
